CREATE DATABASE ecommerce_analysis;
USE ecommerce_analysis;

SHOW TABLES;


-- Question 1: What is the total revenue, total cost, and total profit generated by the business?
SELECT
    SUM(line_revenue) AS total_revenue,
    SUM(line_cost) AS total_cost,
    SUM(line_profit) AS total_profit
FROM order_items;


-- Question 2 — Which product categories generate the highest revenue?
SELECT
    p.category,
    SUM(oi.line_revenue) AS total_revenue
FROM order_items AS oi
JOIN products AS p
    ON oi.product_id = p.product_id
GROUP BY p.category
ORDER BY total_revenue DESC;


-- Question 3 — Which category generates the highest profit?

SELECT
    p.category,
    SUM(oi.line_profit) AS total_profit
FROM order_items AS oi
JOIN products AS p
    ON oi.product_id = p.product_id
GROUP BY p.category
ORDER BY total_profit DESC;

-- Question 4 — Top 10 Products by Revenue

SELECT
    p.product_name,
    SUM(oi.line_revenue) AS total_revenue
FROM order_items AS oi
JOIN products AS p
    ON oi.product_id = p.product_id
GROUP BY p.product_id, p.product_name
ORDER BY total_revenue DESC
LIMIT 10;

-- Question 5 — Which sales channel generates the highest revenue?

SELECT
    o.sales_channel,
    SUM(oi.line_revenue) AS total_revenue
FROM orders AS o
JOIN order_items AS oi
    ON o.order_id = oi.order_id
GROUP BY o.sales_channel
ORDER BY total_revenue DESC;

SELECT DISTINCT sales_channel
FROM orders;

SET SQL_SAFE_UPDATES = 1;

UPDATE orders
SET sales_channel = TRIM(sales_channel);

-- Question 6 — Which payment method generates the highest revenue?

SELECT
    o.payment_method,
    SUM(oi.line_revenue) AS total_revenue
FROM orders AS o
JOIN order_items AS oi
    ON o.order_id = oi.order_id
GROUP BY o.payment_method
ORDER BY total_revenue DESC;

-- one record is blank so 
SELECT DISTINCT payment_method
FROM orders;

SET SQL_SAFE_UPDATES = 0;

UPDATE orders
SET payment_method = TRIM(payment_method);

UPDATE orders
SET payment_method = 'Unknown'
WHERE payment_method IS NULL
   OR payment_method = '';
   
-- Question 7 — What is the monthly revenue trend?

SELECT
    DATE_FORMAT(o.order_date, '%Y-%m') AS order_month,
    SUM(oi.line_revenue) AS total_revenue
FROM orders AS o
JOIN order_items AS oi
    ON o.order_id = oi.order_id
GROUP BY order_month
ORDER BY order_month;

-- One data issue to investigate
SELECT COUNT(*) AS missing_order_dates
FROM orders
WHERE order_date IS NULL;

SELECT COUNT(*) AS blank_order_dates
FROM orders
WHERE order_date = '';

SELECT
    order_date,
    COUNT(*) AS total_orders
FROM orders
GROUP BY order_date
ORDER BY order_date
LIMIT 10;

DESCRIBE orders;

SELECT order_date
FROM orders
WHERE order_date NOT LIKE '____-__-__'
LIMIT 20;

UPDATE orders
SET order_date = STR_TO_DATE(order_date, '%d-%m-%Y')
WHERE order_date LIKE '__-__-____';

UPDATE orders
SET order_date = STR_TO_DATE(order_date, '%d/%m/%Y')
WHERE order_date LIKE '__/__/____';

SELECT DISTINCT order_date
FROM orders
WHERE order_date NOT LIKE '____-__-__';

SELECT order_date
FROM orders
WHERE order_date NOT LIKE '____-__-__';

-- Now let's rerun Question 7 — Monthly Revenue Trend:
SELECT
    DATE_FORMAT(o.order_date, '%Y-%m') AS order_month,
    SUM(oi.line_revenue) AS total_revenue
FROM orders AS o
JOIN order_items AS oi
    ON o.order_id = oi.order_id
GROUP BY order_month
ORDER BY order_month;

-- Question 8 — Revenue by State
SELECT
    c.state,
    SUM(oi.line_revenue) AS total_revenue
FROM customers AS c
JOIN orders AS o
    ON c.customer_id = o.customer_id
JOIN order_items AS oi
    ON o.order_id = oi.order_id
GROUP BY c.state
ORDER BY total_revenue DESC;

-- Q9 — Top 10 Customers by Revenue

SELECT
    c.customer_id,
    c.customer_name,
    SUM(oi.line_revenue) AS total_revenue
FROM customers AS c
JOIN orders AS o
    ON c.customer_id = o.customer_id
JOIN order_items AS oi
    ON o.order_id = oi.order_id
GROUP BY c.customer_id, c.customer_name
ORDER BY total_revenue DESC
LIMIT 10;

-- Q10 — Average Order Value (AOV)

SELECT
    ROUND(AVG(order_revenue), 2) AS average_order_value
FROM (
    SELECT
        o.order_id,
        SUM(oi.line_revenue) AS order_revenue
    FROM orders AS o
    JOIN order_items AS oi
        ON o.order_id = oi.order_id
    GROUP BY o.order_id
) AS order_totals;

-- Q11 — Order Status Analysis
SELECT
    order_status,
    COUNT(*) AS total_orders,
    ROUND(
        COUNT(*) * 100.0 / (SELECT COUNT(*) FROM orders),
        2
    ) AS percentage
FROM orders
GROUP BY order_status
ORDER BY total_orders DESC;

-- Q12 — Return Rate Analysis
SELECT
    COUNT(DISTINCT r.order_id) AS returned_orders,
    COUNT(DISTINCT o.order_id) AS total_orders,
    ROUND(
        COUNT(DISTINCT r.order_id) * 100.0 /
        COUNT(DISTINCT o.order_id),
        2
    ) AS return_rate_percentage
FROM orders AS o
LEFT JOIN returns AS r
    ON o.order_id = r.order_id;
    
--     Q13 — Discount Impact on Profit

SELECT
    CASE
        WHEN discount_pct = 0 THEN 'No Discount'
        WHEN discount_pct <= 10 THEN 'Low Discount (1-10%)'
        WHEN discount_pct <= 20 THEN 'Medium Discount (11-20%)'
        ELSE 'High Discount (21-25%)'
    END AS discount_group,
    ROUND(SUM(line_revenue), 2) AS total_revenue,
    ROUND(SUM(line_profit), 2) AS total_profit,
    ROUND(AVG(line_profit), 2) AS average_profit
FROM order_items
GROUP BY discount_group
ORDER BY total_profit DESC;

-- Next: Q14 — Year-over-Year Revenue Growth

WITH yearly_revenue AS (
    SELECT
        YEAR(o.order_date) AS order_year,
        SUM(oi.line_revenue) AS total_revenue
    FROM orders o
    JOIN order_items oi
        ON o.order_id = oi.order_id
    GROUP BY YEAR(o.order_date)
),
revenue_comparison AS (
    SELECT
        order_year,
        total_revenue,
        LAG(total_revenue) OVER (
            ORDER BY order_year
        ) AS previous_year_revenue
    FROM yearly_revenue
)
SELECT
    order_year,
    ROUND(total_revenue, 2) AS total_revenue,
    ROUND(previous_year_revenue, 2) AS previous_year_revenue,
    ROUND(
        (total_revenue - previous_year_revenue)
        * 100.0 / previous_year_revenue, 2
    ) AS growth_percentage
FROM revenue_comparison;

-- question — Q15: Top 10 Most Profitable Products

SELECT
    p.product_name,
    p.category,
    ROUND(SUM(oi.line_profit), 2) AS total_profit
FROM products p
JOIN order_items oi
    ON p.product_id = oi.product_id
GROUP BY
    p.product_id,
    p.product_name,
    p.category
ORDER BY total_profit DESC
LIMIT 10;